using System;using System.Collections.Generic;using System.Linq;using System.IO;using System.Text;using System.Web.Script.Serialization;
namespace F1Manager {public static class Engine {
public static double Clamp(double v,double a,double b){return Math.Max(a,Math.Min(b,v));}
public static double Rand(Career s){s.Seed=unchecked(s.Seed*1664525+1013904223);return s.Seed/4294967296.0;}
public static Team Team(Career s,int id){return s.Teams.First(t=>t.Id==id);}
public static Person Person(Career s,int id){return s.People.First(p=>p.Id==id);}
public static IEnumerable<Person> Drivers(Career s,int team){return s.People.Where(p=>p.Kind==0&&!p.Retired&&p.Deal!=null&&p.Deal.Team==team&&p.Deal.Start<=s.Year&&p.Deal.Until>=s.Year);}
public static Person Staff(Career s,int team,int kind,int seat=0){return s.People.FirstOrDefault(p=>!p.Retired&&p.Kind==kind&&p.Deal!=null&&p.Deal.Team==team&&p.Deal.Seat==seat&&p.Deal.Start<=s.Year&&p.Deal.Until>=s.Year);}
public static double Quality(Career s,int team,int kind){var p=Staff(s,team,kind);return p==null?50:p.Rating;}
public static double Market(Person p){return Math.Round(p.Kind==0?Math.Max(1,(p.Rating-65)*.27)+p.Wins*.055+p.Titles*2.1:Math.Max(.25,(p.Rating-50)*(p.Kind==1?.15:p.Kind==5?.027:.065)),2);}
public static string Money(double v){return "$"+v.ToString("0.00",System.Globalization.CultureInfo.InvariantCulture)+" млн";}
public static void Note(Career s,string msg){s.News.Insert(0,new News{Year=s.Year,Day=s.Day,Text=msg});if(s.News.Count>200)s.News.RemoveRange(200,s.News.Count-200);}
public static void Pay(Career s,string text,double amount){s.Cash+=amount;s.Ledger.Insert(0,new Ledger{Year=s.Year,Text=text,Value=amount});}
public static int Capacity(Team t){return 10+(t.Facilities[3].Level-1)*2;}
public static int Slots(Team t){return 2+(t.Facilities[3].Level-1)/2;}
public static int Assigned(Career s,Team t){return t.Projects.Sum(p=>p.Engineers);}
public static double Stat(Team t,int n){if(n==1)return t.EngineRating;if(n==5)return Clamp((t.Base[5]+t.EngineReliability)*.5+t.Parts.Where(p=>Data.Parts.First(x=>x.Key==p.Key).Stat==5).Sum(p=>p.Bonus),40,99);return Clamp(t.Base[n]+t.Parts.Where(p=>Data.Parts.First(x=>x.Key==p.Key).Stat==n).Sum(p=>p.Bonus),40,99);}
public static double Car(Team t,Track track){return CarModel.Score(t,track);}
public static double Chemistry(Career s,Person p){var t=Team(s,p.Deal.Team);double v;return t.Chemistry.TryGetValue(p.Id.ToString(),out v)?v:0;}
public static void UpdateChemistry(Career s){foreach(var t in s.Teams)foreach(var d in Drivers(s,t.Id)){var re=Staff(s,t.Id,5,d.Deal.Seat);if(re==null){t.Chemistry[d.Id.ToString()]=0;continue;}int old;if(!t.Pairs.TryGetValue(d.Id.ToString(),out old)||old!=re.Id){t.Pairs[d.Id.ToString()]=re.Id;t.Chemistry[d.Id.ToString()]=0;}double c=Chemistry(s,d);t.Chemistry[d.Id.ToString()]=Clamp(c+(100-c)*(.023+.003*t.Facilities[4].Level),0,99.5);}}
public static void Announce(Career s){foreach(var p in s.People.Where(p=>p.Kind==0&&!p.Retired&&p.RetireYear==0&&p.Age>=36)){if(p.Age>=48||Rand(s)<.035+(p.Age-36)*.055){p.RetireYear=s.Year;Note(s,p.Name+": сезон "+s.Year+" — последний в карьере.");}}}
public static void Lock(Career s){if(s.Weekend!=null&&s.Weekend.Live!=null&&s.Weekend.Live.Started&&!s.Weekend.Live.Finished)throw new Exception("Завершите текущую сессию.");if(s.Stage>0)throw new Exception("Состав и разработка фиксированы до конца уикенда.");}
public static Project Estimate(Career s,Component part,int engineers,bool nextYear=false){return EstimateFor(s,Team(s,s.Player),part,engineers,nextYear);}
public static Project EstimateFor(Career s,Team t,Component part,int engineers,bool nextYear=false){double q=(Quality(s,t.Id,part.Stat==0?3:4)+Quality(s,t.Id,4))*.5;int level=t.Facilities[part.Facility].Level;double speed=1+.06*(t.Facilities[2].Level-1)+.045*(engineers-1)+(q-70)*.002;int design=(int)Math.Ceiling(part.Days*.68/speed),production=(int)Math.Ceiling(part.Days*.32/(1+.05*(t.Facilities[2].Level-1)));double risk=Clamp(.39-(q-50)*.004-(level-1)*.035-(engineers-1)*.019-(t.Facilities[1].Level-1)*.012,.025,.55);var old=(nextYear?t.NextParts:t.Parts).FirstOrDefault(p=>p.Key==part.Key);double diminishing=old==null?1:1/(1+old.Bonus*.15);return new Project{Key=part.Key,TargetYear=s.Year+(nextYear?1:0),Engineers=engineers,Start=s.Day,DesignEnd=s.Day+Math.Max(2,design),Due=s.Day+Math.Max(2,design)+Math.Max(2,production),Cost=Math.Round(part.Price*(1+.045*(engineers-1)),2),Gain=Math.Round(part.Gain*(1+.05*(level-1))*(part.Stat==0?1+.05*(t.Facilities[1].Level-1):1)*diminishing,2),Failure=risk};}
public static void Develop(Career s,string key,int engineers,bool nextYear=false,string focus="balanced"){Lock(s);if(s.SeasonDone)throw new Exception("Откройте межсезонье.");var t=Team(s,s.Player);var part=Data.Parts.First(p=>p.Key==key);if(nextYear&&!Research.NextYearOpen(s))throw new Exception("Разработка следующего болида откроется с дня "+Research.UnlockDay+".");if(t.Projects.Count>=Slots(t))throw new Exception("Все слоты разработки заняты. Улучшите инженерный отдел или дождитесь поставки.");if(t.Projects.Any(p=>p.Key==key&&(p.TargetYear==0?s.Year:p.TargetYear)==s.Year+(nextYear?1:0)))throw new Exception("Эта деталь уже разрабатывается.");if(engineers<1||engineers>Capacity(t)-Assigned(s,t))throw new Exception("Недостаточно свободных инженеров.");if(!CarModel.FocusOptions(key).Contains(focus))throw new Exception("Неизвестное направление разработки.");var project=Estimate(s,part,engineers,nextYear);project.Focus=focus;if(s.Cash<project.Cost)throw new Exception("Недостаточно средств.");if(s.Spent+project.Cost>95)throw new Exception("Достигнут сезонный лимит разработки $95 млн.");s.Spent+=project.Cost;Pay(s,part.Name+" / "+project.TargetYear+" — проект",-project.Cost);t.Projects.Add(project);Note(s,part.Name+" / "+project.TargetYear+": "+engineers+" инженеров; проектирование до дня "+project.DesignEnd+", поставка в день "+project.Due+".");}
public static void Advance(Career s,int day){if(day<s.Day)return;int first=s.Day;for(int d=first;d<=day;d++){s.Day=d;foreach(var t in s.Teams){foreach(var f in t.Facilities.Where(f=>f.Building&&f.Due<=d)){f.Level++;f.Building=false;if(t.Id==s.Player)Note(s,"Строительство отдела завершено. Новый уровень: "+f.Level+".");}foreach(var p in t.Projects.ToList()){if(!p.Evaluated&&p.DesignEnd<=d){p.Evaluated=true;p.Failed=Rand(s)<p.Failure;if(p.Failed){Engineering.BenchFailure(s,t,p);t.Projects.Remove(p);if(t.Id==s.Player)Note(s,"НЕУДАЧНАЯ ДЕТАЛЬ: "+Data.Parts.First(x=>x.Key==p.Key).Name+" не прошла стендовые испытания. Затраты списаны; инженеры и слот освобождены.");continue;}if(t.Id==s.Player)Note(s,Data.Parts.First(x=>x.Key==p.Key).Name+": проект прошёл испытания, начато производство. Инженеры заняты до поставки.");}if(p.Evaluated&&!p.Failed&&p.Due<=d){bool future=p.TargetYear>s.Year;var inventory=future?t.NextParts:t.Parts;var item=inventory.FirstOrDefault(x=>x.Key==p.Key);if(item==null){item=new Installed{Key=p.Key,Version=0};inventory.Add(item);}item.Version++;Engineering.Install(s,t,p,item);t.Projects.Remove(p);var title=Data.Parts.First(x=>x.Key==p.Key).Name;if(t.Id==s.Player)Note(s,(future?"ГОТОВО К "+p.TargetYear+": ":"ДОСТАВЛЕНО: ")+title+" v"+item.Version+(future?". Не используется на текущем болиде.":". Установлено на оба болида; предстоит проверка на трассе."));else Note(s,t.Name+": "+title+" v"+item.Version+(future?" подготовлена к "+p.TargetYear:" установлена на болид" )+".");}}}Research.PlanDay(s);}}
public static void DayForward(Career s){Lock(s);if(s.SeasonDone)throw new Exception("Откройте следующий сезон.");int limit=Data.Tracks[s.Round].Day-2;if(s.Day>=limit)throw new Exception("Наступил гоночный уикенд. Пора на трассу.");Advance(s,s.Day+1);}
public static void FacilityUpgrade(Career s,int index){Lock(s);var f=Team(s,s.Player).Facilities[index];if(f.Building||f.Level>=5)throw new Exception("Отдел уже строится или достиг уровня 5.");double cost=5+f.Level*5;if(s.Cash<cost)throw new Exception("Недостаточно средств.");Pay(s,Data.Facilities[index]+" — модернизация",-cost);f.Building=true;f.Due=s.Day+22+f.Level*9;Note(s,Data.Facilities[index]+": строительство до дня "+f.Due+". Действующие бонусы сохраняются.");}
public static double Severance(Career s,Person p){if(p.Deal==null)return 0;return Math.Max(0,Math.Min(p.Deal.Salary*Math.Max(0,p.Deal.Until-s.Year+1),p.Deal.Salary*p.Deal.Severance/12.0));}
public static Quote Negotiate(Career s,Person p,int start,int seat){var t=Team(s,s.Player);double results=t.Points/Math.Max(1.0,s.Round)/12.0;int mood=(int)Clamp(p.Mood+results*6+(t.Facilities[4].Level-1)*4+(Quality(s,t.Id,1)-75)*.25-(p.Deal!=null&&p.Deal.Team!=s.Player?5:0),10,95);double current=p.Deal==null?0:p.Deal.Salary;double salary=Math.Round(Math.Max(Market(p)*(.95+(70-mood)*.005),current*(p.Deal!=null&&p.Deal.Team==s.Player?1:1.05)),2);double fee=0;if(p.Deal!=null&&p.Deal.Team!=s.Player&&p.Deal.Until>=start)fee=p.Deal.Salary*(p.Deal.Until-start+1)*.5;var old=s.People.FirstOrDefault(x=>x.Kind==p.Kind&&x.Id!=p.Id&&x.Deal!=null&&x.Deal.Team==s.Player&&x.Deal.Seat==seat);return new Quote{Salary=salary,Mood=mood,Fee=fee,Bonus=salary*(start>s.Year?.05:.1),Compensation=old==null?0:(start>s.Year?old.Deal.Until>=start?Math.Min(old.Deal.Salary*(old.Deal.Until-start+1),old.Deal.Salary*old.Deal.Severance/12.0):0:Severance(s,old)),MinSeverance=p.Rating>=90?12:6,Reason="Настрой: результаты коллектива, прежняя зарплата, руководство и отдел персонала."};}
public static void Sign(Career s,int id,int start,int seat,double salary,int years,int severance,string role){Lock(s);var p=Person(s,id);if(p.Retired||p.RetireYear>0&&p.RetireYear<start)throw new Exception("Пилот завершает карьеру до начала контракта.");if(start!=s.Year&&start!=s.Year+1||years<1||years>4||salary<0||double.IsNaN(salary)||double.IsInfinity(salary))throw new Exception("Некорректные параметры контракта.");if(p.RetireYear>0&&start+years-1>p.RetireYear)throw new Exception("Пилот согласен выступать только до конца последнего объявленного сезона.");if(seat<0||seat>(p.Kind==0||p.Kind==5?1:0))throw new Exception("Неверное место в составе.");if(s.Bookings.Any(b=>b.Person==id)||s.Bookings.Any(b=>Person(s,b.Person).Kind==p.Kind&&b.Deal.Seat==seat&&b.Deal.Team==s.Player))throw new Exception("Человек или это место уже забронированы. Сначала отмените прежнее соглашение.");var q=Negotiate(s,p,start,seat);if(salary+0.001<q.Salary)throw new Exception("Предложение отклонено: запрошено от "+Money(q.Salary)+" в год. "+q.Reason);if(severance<q.MinSeverance||severance>24)throw new Exception("Требуются отступные не меньше "+q.MinSeverance+" месяцев зарплаты.");if(p.Kind==0&&(p.Rating>=94||p.Titles>=2)&&role!="Первый пилот")throw new Exception("Пилот требует статус первого номера.");if(p.Kind==0&&role=="Первый пилот"){var first=s.People.FirstOrDefault(x=>x.Id!=id&&x.Kind==0&&x.Deal!=null&&x.Deal.Team==s.Player&&x.Deal.Seat!=seat&&x.Deal.Until>=start&&x.Deal.Role=="Первый пилот");if(first!=null&&!s.Bookings.Any(b=>b.Deal.Seat==first.Deal.Seat&&b.Deal.Team==s.Player&&b.Deal.Start==start))throw new Exception("В команде уже есть первый номер: "+first.Name+".");if(s.Bookings.Any(b=>b.Deal.Team==s.Player&&b.Deal.Start==start&&Person(s,b.Person).Kind==0&&b.Deal.Role=="Первый пилот"))throw new Exception("Первый номер на будущий сезон уже забронирован.");}
double bonus=salary*(start>s.Year?.05:.1),total=q.Fee+q.Compensation+bonus;if(s.Cash<total)throw new Exception("На выкуп, компенсацию и бонус нужно "+Money(total)+".");Pay(s,p.Name+" — контракт",-total);var deal=new Contract{Team=s.Player,Seat=seat,Start=start,Until=start+years-1,Salary=salary,Severance=severance,Role=p.Kind==0?role:Data.Roles[p.Kind]};
if(start>s.Year){s.Bookings.Add(new Booking{Person=id,Deal=deal,Paid=total});if(p.Deal!=null&&p.Deal.Team!=s.Player&&p.Deal.Until>=start)p.Deal.Until=start-1;Note(s,p.Name+" забронирован: "+start+"–"+deal.Until+". Начало — следующий сезон.");}
else {var old=s.People.FirstOrDefault(x=>x.Id!=id&&x.Kind==p.Kind&&x.Deal!=null&&x.Deal.Team==s.Player&&x.Deal.Seat==seat);if(old!=null)old.Deal=null;p.Deal=deal;p.Mood=70;ResetChemistry(s,p);Note(s,p.Name+": контракт действует немедленно до "+deal.Until+". Зарплата "+Money(salary)+".");FillAI(s);}}
public static void ResetChemistry(Career s,Person p){if(p.Deal==null)return;var t=Team(s,p.Deal.Team);if(p.Kind==0)t.Chemistry[p.Id.ToString()]=0;if(p.Kind==5){var d=Drivers(s,t.Id).FirstOrDefault(x=>x.Deal.Seat==p.Deal.Seat);if(d!=null){t.Pairs[d.Id.ToString()]=p.Id;t.Chemistry[d.Id.ToString()]=0;}}}
public static void Fire(Career s,int id){Lock(s);var p=Person(s,id);if(p.Deal==null||p.Deal.Team!=s.Player)throw new Exception("Этот человек не работает в вашей команде.");if(s.Bookings.Any(b=>b.Person==id))throw new Exception("Сначала отмените будущее соглашение этого человека.");double fee=Severance(s,p);if(s.Cash<fee)throw new Exception("Недостаточно средств на отступные.");Pay(s,p.Name+" — увольнение",-fee);p.Deal=null;Note(s,p.Name+" уволен; отступные "+Money(fee)+".");}
public static void Cancel(Career s,int id){Lock(s);var b=s.Bookings.First(x=>x.Person==id);s.Bookings.Remove(b);Note(s,"Будущий контракт "+Person(s,id).Name+" отменён. Выплаченный бонус и компенсации не возвращаются.");}
public static void EngineDeal(Career s,string provider,int years){Lock(s);var t=Team(s,s.Player);if(t.Works)throw new Exception("Заводская команда не может выбирать поставщика двигателя.");if(provider=="GM"&&s.Year<2028)throw new Exception("GM доступен с 2028 года.");if(years<2||years>4)throw new Exception("Контракт поставки на 2–4 сезона.");int i=Array.IndexOf(Data.Engines,provider);if(i<0)throw new Exception("Поставщик не найден.");bool now=s.Preseason&&s.Round==0;if(now&&t.EngineUntil>=s.Year&&t.Engine!=provider){double fee=Data.EnginePrice[Array.IndexOf(Data.Engines,t.Engine)]*.25;if(s.Cash<fee+3)throw new Exception("Недостаточно средств на расторжение и новый договор.");Pay(s,"Расторжение договора двигателя",-fee);}if(s.Cash<3)throw new Exception("Бонус поставщику: $3 млн.");Pay(s,"Договор поставки "+provider,-3);if(now){t.Engine=provider;t.EngineUntil=s.Year+years-1;t.EngineRating=Data.EnginePower[i];t.EngineReliability=Data.EngineReliability[i];}else {t.NextEngine=provider;t.NextEngineYear=s.Year+1;t.NextEngineUntil=s.Year+years;}Note(s,"Договор двигателя "+provider+": "+(now?"сейчас":"со следующего сезона")+", "+years+" года.");}
public static void EngineUpgrade(Career s){Lock(s);var t=Team(s,s.Player);if(!t.Works||!s.Preseason||s.Round!=0)throw new Exception("Двигатель можно улучшать только заводской команде в межсезонье.");if(t.EngineUpgradedYear==s.Year)throw new Exception("Моторная программа на этот год уже выполнена.");if(s.Cash<14)throw new Exception("Необходимо $14 млн.");Pay(s,"Межсезонная моторная программа",-14);t.EngineRating=Clamp(t.EngineRating+2+(Quality(s,t.Id,4)-70)*.035,50,99);t.EngineReliability=Clamp(t.EngineReliability+2,50,99);t.EngineUpgradedYear=s.Year;Note(s,"Заводская моторная программа завершена. Параметры зафиксированы до конца сезона.");}
public static string[] Sessions(Career s){return Data.Tracks[s.Round].Sprint?new[]{"FP1","SQ1","SQ2","SQ3","Спринт","Q1","Q2","Q3","Гонка"}:new[]{"FP1","FP2","FP3","Q1","Q2","Q3","Гонка"};}
public static bool SprintPlan(Career s){return !s.SeasonDone&&Sessions(s)[s.Stage]=="Спринт";}
public static int PlanLaps(Career s){return SprintPlan(s)?(int)Math.Ceiling(Data.Tracks[s.Round].Laps*.33):Data.Tracks[s.Round].Laps;}
public static Plan DefaultPlan(Career s,int mode){int laps=PlanLaps(s);if(SprintPlan(s))return new Plan{Mode=mode,Tyres=new List<string>{mode==3?"I":mode==2?"S":mode==0?"H":"M"}};double[] fractions=mode==0?new[]{.43}:mode==1?new[]{.3,.68}:mode==2?new[]{.19,.46,.75}:new[]{.5};return new Plan{Mode=mode,Stops=fractions.Select(v=>(int)Math.Round(laps*v)).ToList(),Tyres=mode==0?new List<string>{"M","H"}:mode==1?new List<string>{"M","H","M"}:mode==2?new List<string>{"S","M","M","S"}:new List<string>{"I","I"}};}
public static int Recommended(Career s){return s.Weekend!=null&&s.Weekend.Weather=="Дождь"?3:Data.Tracks[s.Round].Wear>=4?1:0;}
public static Plan PlanFor(Career s,int id){Plan p;return s.Plans.TryGetValue(id.ToString(),out p)?p:DefaultPlan(s,Recommended(s));}
public static void SetPlan(Career s,int id,Plan plan){if(!Drivers(s,s.Player).Any(p=>p.Id==id))throw new Exception("Стратегия доступна только пилотам вашей команды.");if(s.Weekend!=null&&s.Weekend.Live!=null&&!s.Weekend.Live.Finished)throw new Exception("План на сессию уже зафиксирован. Изменить стратегию можно до старта.");int laps=PlanLaps(s);if(plan==null||plan.Stops==null||plan.Tyres==null||plan.Mode<0||plan.Mode>=Data.Strategies.Length||plan.Stops.Count<(SprintPlan(s)?0:1)||plan.Stops.Count>3||plan.Tyres.Count!=plan.Stops.Count+1||plan.Stops.Any(l=>l<2||l>laps-2)||!plan.Stops.SequenceEqual(plan.Stops.OrderBy(x=>x).Distinct())||plan.Tyres.Any(x=>!new[]{"S","M","H","I","W"}.Contains(x)))throw new Exception("Проверьте круги пит-стопов и составы шин.");if(!SprintPlan(s)&&plan.Tyres.All(x=>x=="S"||x=="M"||x=="H")&&plan.Tyres.Distinct().Count()<2)throw new Exception("Сухая гонка требует два разных состава.");s.Plans[id.ToString()]=plan;}
public static string Ready(Career s){if(s.SeasonDone)return "Сезон завершён.";if(Drivers(s,s.Player).Count()!=2)return "Подпишите контракты с двумя пилотами.";var t=Team(s,s.Player);if(!t.Works&&t.EngineUntil<s.Year)return "Истёк договор двигателя. Выберите поставщика.";return "";}
public static bool IsQualifying(string name){return name!=null&&(name.StartsWith("Q")||name.StartsWith("SQ"));}
static void SetQualifyingConditions(Career s,LiveSession live){bool sprint=live.Name.StartsWith("SQ");string weather=sprint?s.Weekend.SprintQualWeather:s.Weekend.QualWeather;if(weather==null){weather=s.Weekend.Results.Where(r=>IsQualifying(r.Name)&&r.Name.StartsWith("SQ")==sprint).Select(r=>r.Weather).FirstOrDefault(w=>w=="Сухо"||w=="Дождь")??live.Weather;if(sprint)s.Weekend.SprintQualWeather=weather;else s.Weekend.QualWeather=weather;}live.Weather=weather;s.Weekend.Weather=weather;live.WeatherAt=double.MaxValue;}
public static void PrepareWeekend(Career s){if(s.Weekend==null)s.Weekend=new Weekend{Weather=WeatherModel.AllowsRain(s)&&Rand(s)<Data.Tracks[s.Round].Rain?"Дождь":"Сухо"};if(s.Stage==0&&s.Weekend.Results.Count==0&&(s.Weekend.Live==null||!s.Weekend.Live.Started)&&!WeatherModel.AllowsRain(s)){s.Weekend.Weather="Сухо";s.Weekend.RainAffected=false;}if(s.Weekend.Weather=="Дождь")s.Weekend.RainAffected=true;}
public static void Start(Career s){string problem=Ready(s);if(problem!="")throw new Exception(problem);PrepareWeekend(s);if(s.Weekend.Live!=null&&!s.Weekend.Live.Finished){s.Weekend.Live.Paused=false;if(IsQualifying(s.Weekend.Live.Name))SetQualifyingConditions(s,s.Weekend.Live);return;}var track=Data.Tracks[s.Round];s.Preseason=false;int day=track.Day-2;if(s.Stage>=Sessions(s).Length-4)day=track.Day-1;if(Sessions(s)[s.Stage]=="Гонка")day=track.Day;Advance(s,Math.Max(s.Day,day));var live=new LiveSession{Name=Sessions(s)[s.Stage],Weather=s.Weekend.Weather,Started=true,Paused=false};bool race=live.Name=="Гонка"||live.Name=="Спринт",sq=live.Name.StartsWith("SQ"),qual=live.Name.StartsWith("Q")||sq;live.TargetLaps=live.Name=="Спринт"?(int)Math.Ceiling(track.Laps*.33):race?track.Laps:0;live.Duration=live.Name.StartsWith("FP")?3600:qual?(live.Name.EndsWith("1")?(sq?720:1080):live.Name.EndsWith("2")?(sq?600:900):(sq?480:720)):0;live.WeatherAt=!qual&&Rand(s)<WeatherModel.ChangeChance(s,live.Weather)?(race?track.BaseLap*live.TargetLaps:live.Duration)*(.3+Rand(s)*.4):double.MaxValue;if(qual)SetQualifyingConditions(s,live);var all=s.People.Where(p=>p.Kind==0&&!p.Retired&&p.Deal!=null&&p.Deal.Until>=s.Year).ToList();List<int> grid=live.Name=="Спринт"?s.Weekend.SQ:s.Weekend.Qual;var qualification=sq?s.Weekend.SQ:s.Weekend.Qual;if(qual&&live.Name.EndsWith("2"))all=all.Where(d=>qualification.Take(16).Contains(d.Id)).ToList();if(qual&&live.Name.EndsWith("3"))all=all.Where(d=>qualification.Take(10).Contains(d.Id)).ToList();foreach(var p in all){var e=new Entry{Id=p.Id,Team=p.Deal.Team,Garage=!race};var plan=p.Deal.Team==s.Player?PlanFor(s,p.Id):DefaultPlan(s,Recommended(s));e.Plan=plan.Mode;e.Tyre=race?plan.Tyres[0]:live.Weather=="Дождь"?"I":qual?"S":"M";e.Wait=race?0:15+Rand(s)*100;e.Status=race?"На решётке":"В гараже";if(race){int pos=grid.IndexOf(p.Id);if(pos<0)pos=all.IndexOf(p);e.Remaining=LapTime(s,live,e)+pos*.22;e.LapDuration=e.Remaining;}live.Entries.Add(e);}live.Log.Add("Сессия "+live.Name+" началась. Погода: "+live.Weather+".");s.Weekend.Live=live;if(race)RaceDirector.Initialize(s,grid);}
public static double LapTime(Career s,LiveSession live,Entry e){var p=Person(s,e.Id);var t=Team(s,e.Team);var track=Data.Tracks[s.Round];double pace=Car(t,track)*.55+p.Rating*.45;double time=track.BaseLap+(90-pace)*.20+(Rand(s)-.5)*.9;var re=Staff(s,t.Id,5,p.Deal.Seat);time-=(re==null?0:(re.Rating-65)*.006+Chemistry(s,p)*.005);time-=(Quality(s,t.Id,2)-70)*.004;bool wet=live.Weather=="Дождь";time+=wet?(e.Tyre=="I"?8:e.Tyre=="W"?11:28):(e.Tyre=="I"?9:e.Tyre=="W"?15:e.Tyre=="H"?.65:e.Tyre=="S"?-.6:0);if(IsQualifying(live.Name))time-=.1*(live.Name[live.Name.Length-1]-'1');double life=e.Tyre=="S"?17:e.Tyre=="M"?29:e.Tyre=="H"?43:30;double wear=e.StintLaps/life*(.65+track.Wear*.1)*(1+(80-CarModel.Metric(t,5))*.005)*(1+Math.Max(0,CarModel.Profile(track).TyreHeat-CarModel.Metric(t,7))*.009);time+=Math.Pow(Math.Max(0,wear-.45),2)*2.4;time+=e.Damage+Math.Max(0,CarModel.Profile(track).EngineHeat-CarModel.Metric(t,6))*.018;if(live.SafetyUntil>live.Elapsed)time*=1.38;return Math.Max(55,time);}
public static void Incident(Career s,string msg){var live=s.Weekend.Live;live.Event=msg;live.AwaitingEvent=true;live.Log.Insert(0,Clock(live.Elapsed)+"  "+msg);if(live.Log.Count>80)live.Log.RemoveAt(live.Log.Count-1);}
public static string Clock(double t){return ((int)t/60).ToString("00")+":"+((int)t%60).ToString("00");}
public static List<Entry> Order(Career s){var live=s.Weekend.Live;bool race=live.TargetLaps>0;if(live.TickRace)return live.Entries.OrderBy(e=>e.Dnf?1:0).ThenBy(e=>e.RacePosition).ToList();if(!race)return live.Entries.OrderBy(e=>e.Best).ThenByDescending(e=>e.Lap).ToList();return live.Entries.OrderBy(e=>e.Dnf?2:e.Finished?0:1).ThenBy(e=>e.Finished?e.FinishTime:0).ThenByDescending(e=>e.Lap+(e.LapDuration>0?1-e.Remaining/e.LapDuration:0)).ToList();}
public static void Pit(Career s,int id,string tyre){var live=s.Weekend==null?null:s.Weekend.Live;if(live==null||live.Finished||live.TargetLaps==0)throw new Exception("Ручной пит-стоп доступен в гонке или спринте.");var e=live.Entries.FirstOrDefault(x=>x.Id==id);if(e==null||e.Dnf||e.Finished)throw new Exception("Машина не участвует в гонке.");if(!new[]{"S","M","H","I","W"}.Contains(tyre))throw new Exception("Неизвестные шины.");e.PitRequested=true;e.NextTyre=Array.IndexOf(new[]{"S","M","H","I","W"},tyre);live.Log.Insert(0,Clock(live.Elapsed)+"  "+Person(s,id).Name+": вызов в боксы на "+tyre+".");}
public static bool Tick(Career s,double seconds,bool automaticWeather=false){var l=s.Weekend==null?null:s.Weekend.Live;if(l==null||l.Finished||l.Paused)return false;if(l.TickRace)return RaceDirector.Advance(s,seconds,automaticWeather);bool eventOccurred=false;int steps=(int)Math.Ceiling(seconds/.5);double dt=seconds/Math.Max(1,steps);for(int k=0;k<steps;k++){if(l.Finished)break;l.Elapsed+=dt;if(l.SafetyUntil>0&&l.Elapsed>=l.SafetyUntil){l.SafetyUntil=0;Incident(s,"SAFETY CAR уходит в боксы. Гонка возобновляется.");eventOccurred=true;}if(!IsQualifying(l.Name)&&!l.WeatherChanged&&l.Elapsed>=l.WeatherAt&&(l.Weather=="Дождь"||WeatherModel.AllowsRain(s))){l.WeatherChanged=true;l.Weather=l.Weather=="Дождь"?"Сухо":"Дождь";s.Weekend.Weather=l.Weather;if(l.Weather=="Дождь")s.Weekend.RainAffected=true;Incident(s,"ИЗМЕНЕНИЕ ПОГОДЫ: "+l.Weather+(automaticWeather?". Инженер автоматически подбирает шины.":". Проверьте шины и вызовите пилотов в боксы при необходимости."));eventOccurred=true;}
foreach(var e in l.Entries){if(e.Finished||e.Dnf)continue;if(e.Garage){if(l.Elapsed>=l.Duration){e.Finished=true;continue;}e.Wait-=dt;if(e.Wait<=0&&l.Elapsed<l.Duration-75){e.Garage=false;e.RunLaps=0;e.OutLap=true;e.Tyre=l.Weather=="Дождь"?"I":l.Name.StartsWith("FP")?"M":"S";e.StintLaps=0;e.TyreWear=0;e.Status="Выезд / быстрый круг";e.Remaining=LapTime(s,l,e)+3;e.LapDuration=e.Remaining;}continue;}e.Remaining-=dt;e.Total+=dt;if(e.Remaining>0)continue;double over=-e.Remaining;e.Lap++;e.StintLaps++;if(!e.OutLap)e.RunLaps++;e.TyreWear=Clamp(e.StintLaps/(e.Tyre=="S"?22.0:e.Tyre=="H"?48.0:34.0)*100,0,100);e.Last=e.LapDuration;if(!e.OutLap)e.Best=Math.Min(e.Best,e.Last);var person=Person(s,e.Id);var t=Team(s,e.Team);
if(l.TargetLaps==0){e.OutLap=false;if(l.Elapsed>=l.Duration){e.Finished=true;e.Status="Клетчатый флаг";}else if(e.RunLaps>=(l.Name.StartsWith("FP")?4:2)){e.Garage=true;e.Wait=l.Name.StartsWith("FP")?75+Rand(s)*150:50+Rand(s)*100;e.Status="В гараже";e.StintLaps=0;}else{e.LapDuration=LapTime(s,l,e);e.Remaining=e.LapDuration-over;e.Status="Быстрый круг";}continue;}
if(e.Lap>=l.TargetLaps){e.Finished=true;e.FinishTime=l.Elapsed-over;e.Status="Финиш";continue;}
double fail=.00010+(100-CarModel.Metric(t,8))*.000027+Math.Max(0,CarModel.Profile(Data.Tracks[s.Round]).EngineHeat-CarModel.Metric(t,6))*.000012;if(Rand(s)<fail||Rand(s)<.00042){e.Dnf=true;e.Status="Сход";e.Reason=Rand(s)<.5?"Поломка гидравлики":"Контакт / авария";Incident(s,person.Name+": СХОД — "+e.Reason+". "+(e.Team==s.Player?"Очки за эту гонку потеряны.":"Соперник выбыл из борьбы."));eventOccurred=true;if(e.Reason.Contains("авария")){l.SafetyUntil=l.Elapsed+180;Incident(s,"SAFETY CAR: авария на трассе, темп снижен на 3 минуты.");}continue;}
if(e.Damage==0&&Rand(s)<.0007){e.Damage=1.4;Incident(s,person.Name+": повреждение аэродинамики, потеря примерно 1.4 секунды на круге.");eventOccurred=true;}
var plan=e.Team==s.Player?PlanFor(s,e.Id):DefaultPlan(s,e.Plan);int next=e.ScheduledStops<plan.Stops.Count?plan.Stops[e.ScheduledStops]:int.MaxValue;
if(l.Name=="Гонка"&&e.Team==s.Player&&!e.WindowNotified&&e.Lap>=next-2&&e.Lap<next){e.WindowNotified=true;Incident(s,person.Name+": открывается окно пит-стопа. Плановый заезд на круге "+next+"; текущие шины "+e.Tyre+".");eventOccurred=true;}
bool planned=e.Lap>=next;bool aiWeather=(e.Team!=s.Player||automaticWeather)&&((l.Weather=="Дождь"&&e.Tyre!="I"&&e.Tyre!="W")||(l.Weather=="Сухо"&&(e.Tyre=="I"||e.Tyre=="W")));
double pitLoss=0;if(e.PitRequested||planned||aiWeather){string tyre=e.PitRequested?new[]{"S","M","H","I","W"}[e.NextTyre]:aiWeather?(l.Weather=="Дождь"?"I":"M"):plan.Tyres[Math.Min(e.ScheduledStops+1,plan.Tyres.Count-1)];if(automaticWeather){if(l.Weather=="Дождь"&&tyre!="I"&&tyre!="W")tyre="I";if(l.Weather=="Сухо"&&(tyre=="I"||tyre=="W"))tyre="M";}e.Tyre=tyre;e.StintLaps=0;e.Stops++;if(planned)e.ScheduledStops++;e.PitRequested=false;e.WindowNotified=false;pitLoss=(l.SafetyUntil>l.Elapsed?12:21)+2.5+(95-Quality(s,e.Team,2))*.04+(Rand(s)<.07?3:0);e.Status="Пит-стоп → "+tyre;l.Log.Insert(0,Clock(l.Elapsed)+"  "+person.Name+": пит-стоп, "+tyre+", потери "+pitLoss.ToString("0.0")+" с.");}else e.Status="На трассе";e.TyreWear=Clamp(e.StintLaps/(e.Tyre=="S"?22.0:e.Tyre=="H"?48.0:34.0)*100,0,100);e.LapDuration=LapTime(s,l,e)+pitLoss;e.Remaining=e.LapDuration-over;
}
if(l.Entries.All(e=>e.Finished||e.Dnf)){Finish(s);break;}if(l.Log.Count>80)l.Log.RemoveRange(80,l.Log.Count-80);if(eventOccurred)break;}
return eventOccurred;}
public static void SimulateSession(Career s){Start(s);var live=s.Weekend.Live;live.Paused=false;if(live.TickRace){for(int i=0;i<1500&&!live.Finished;i++){live.AwaitingEvent=false;RaceDirector.Step(s,true);}if(!live.Finished)throw new Exception("Не удалось завершить гонку.");return;}for(int i=0;i<2400&&!live.Finished;i++){Tick(s,60,true);live.AwaitingEvent=false;}if(!live.Finished)throw new Exception("Не удалось завершить сессию. Исходная карьера сохранена.");}
public static void Finish(Career s){var live=s.Weekend.Live;if(live.Finished)return;live.Finished=true;live.Paused=true;var rows=Order(s).Select((e,i)=>new Row{Id=e.Id,Team=e.Team,Position=i+1,Laps=e.Lap,Best=e.Best,Time=live.TargetLaps>0?e.FinishTime:e.Best,Dnf=e.Dnf,Tyre=e.Tyre,Detail=e.Dnf?e.Reason:"Пит-стопы: "+e.Stops}).ToList();bool sq=live.Name.StartsWith("SQ"),qual=live.Name.StartsWith("Q")||sq;var grid=sq?s.Weekend.SQ:s.Weekend.Qual;if(qual){var ids=rows.Select(r=>r.Id).ToList();if(live.Name.EndsWith("1"))grid=ids;else grid=ids.Concat(grid.Where(id=>!ids.Contains(id))).ToList();if(sq)s.Weekend.SQ=grid;else s.Weekend.Qual=grid;if(live.Name.EndsWith("3")){foreach(int id in grid.Skip(10)){var old=s.Weekend.Results.Where(r=>r.Name.StartsWith(sq?"SQ":"Q")).SelectMany(r=>r.Rows).Last(r=>r.Id==id);rows.Add(new Row{Id=id,Team=old.Team,Position=rows.Count+1,Laps=old.Laps,Time=old.Time,Best=old.Best,Tyre=old.Tyre,Detail="Выбыл в раннем сегменте"});}}}
bool race=live.TargetLaps>0;if(race){int[] points=live.Name=="Спринт"?new[]{8,7,6,5,4,3,2,1}:new[]{25,18,15,12,10,8,6,4,2,1};foreach(var r in rows){var p=Person(s,r.Id);r.Points=!r.Dnf&&r.Position<=points.Length?points[r.Position-1]:0;p.Points+=r.Points;Team(s,r.Team).Points+=r.Points;if(live.Name=="Гонка"){p.Finishes.Add(r.Dnf?99:r.Position);if(!r.Dnf&&r.Position==1){p.Wins++;Team(s,r.Team).Wins++;}if(!r.Dnf&&r.Position<=3)p.Podiums++;}}}
s.Weekend.Results.Add(new SessionResult{Name=live.Name,Weather=live.Weather,Rows=rows});s.Stage++;if(live.Name=="Гонка"){EndRound(s,rows);}else {if(live.Name=="Спринт")s.Plans.Clear();Note(s,live.Name+": лучший результат — "+Person(s,rows[0].Id).Name+".");}}
public static List<Person> Standings(Career s){return s.People.Where(p=>p.Kind==0&&(p.Deal!=null||p.Points>0)).OrderByDescending(p=>p.Points).ThenByDescending(p=>p.Finishes.Count(x=>x==1)).ThenByDescending(p=>p.Finishes.Count(x=>x==2)).ThenByDescending(p=>p.Finishes.Count(x=>x==3)).ThenByDescending(p=>p.Rating).ToList();}
public static void EndRound(Career s,List<Row> rows){var t=Team(s,s.Player);double salary=s.People.Where(p=>p.Deal!=null&&p.Deal.Team==s.Player&&p.Deal.Until>=s.Year).Sum(p=>p.Deal.Salary)/Data.Tracks.Length;int engineIndex=Array.IndexOf(Data.Engines,t.Engine);double sponsor=(7.5+rows.Where(r=>r.Team==s.Player).Sum(r=>r.Points)*.12)*(1+.08*(t.Facilities[5].Level-1))*(1+(Quality(s,t.Id,1)-75)*.002);Pay(s,Data.Tracks[s.Round].Country+" — спонсоры",sponsor);Pay(s,"Этап: зарплаты, мотор и эксплуатация",-salary-2.0-Data.EnginePrice[engineIndex]/Data.Tracks.Length);UpdateChemistry(s);foreach(var p in s.People.Where(p=>p.Deal!=null)){var pos=rows.FindIndex(r=>r.Id==p.Id);p.Mood=Clamp(p.Mood+(p.Kind==0?(pos>=0&&pos<10?1.5:-.5):Team(s,p.Deal.Team).Points>0?.5:-.2),20,90);}s.Archive.Add(new WeekendArchive{Year=s.Year,Round=s.Round,Weather=s.Weekend.Weather,RainAffected=s.Weekend.RainAffected,Sessions=s.Weekend.Results});Note(s,Data.Tracks[s.Round].Country+": победитель — "+Person(s,rows[0].Id).Name+".");Advance(s,Math.Max(s.Day,Data.Tracks[s.Round].Day));Engineering.CompleteRound(s);s.Round++;s.Stage=0;s.Weekend=null;s.Plans.Clear();
if(s.Round>=Data.Tracks.Length){s.SeasonDone=true;var champ=Standings(s)[0];champ.Titles++;var ct=s.Teams.OrderByDescending(x=>x.Points).ThenByDescending(x=>x.Wins).First();s.Hall.Add(new Champion{Year=s.Year,DriverId=champ.Id,TeamId=ct.Id,Driver=champ.Name,Team=ct.Name,DriverPoints=champ.Points,TeamPoints=ct.Points});int place=s.Teams.OrderByDescending(x=>x.Points).ToList().FindIndex(x=>x.Id==s.Player);Pay(s,"Сезонные призовые",35+(s.Teams.Count-place)*3);Note(s,"Чемпион "+s.Year+": "+champ.Name+". Кубок конструкторов: "+ct.Name+". Итог записан в зал славы.");}}
public static Person Generate(Career s,int kind){int n=s.NextId++;string[] fn={"Алекс","Лука","Ноа","Рен","Эмиль","Даниэль","Макс","Адам"},ln={"Марков","Росси","Мартен","Танака","Ларсен","Коста","Фишер","Уолш"};var p=new Person{Id=n,Name=fn[n%8]+" "+ln[(n/8)%8]+" #"+(n/64),Kind=kind,Age=kind==0?18+(int)(Rand(s)*5):30+(int)(Rand(s)*18),Rating=kind==0?69+(int)(Rand(s)*14):68+(int)(Rand(s)*15),Fictional=true,RealRole="Вымышленный выпускник академии"};s.People.Add(p);return p;}
public static void FillAI(Career s){foreach(var t in s.Teams.Where(t=>t.Id!=s.Player))for(int kind=0;kind<=5;kind++)for(int seat=0;seat<(kind==0||kind==5?2:1);seat++){int k=kind,st=seat;if(s.People.Any(p=>p.Kind==k&&p.Deal!=null&&p.Deal.Team==t.Id&&p.Deal.Seat==st&&p.Deal.Until>=s.Year&&!p.Retired))continue;var person=s.People.Where(p=>p.Kind==k&&!p.Retired&&p.Deal==null&&!s.Bookings.Any(b=>b.Person==p.Id)).OrderByDescending(p=>p.Rating).FirstOrDefault()??Generate(s,k);person.Deal=new Contract{Team=t.Id,Seat=seat,Start=s.Year,Until=s.Year+1,Salary=Market(person),Role=kind==0?(seat==0?"Первый пилот":"Равный статус"):Data.Roles[kind]};}}
public static void NextSeason(Career s){if(!s.SeasonDone)throw new Exception("Сначала завершите сезон.");s.Year++;s.Day=0;s.Round=0;s.Stage=0;s.SeasonDone=false;s.Preseason=true;s.Spent=0;s.Weekend=null;s.Plans.Clear();foreach(var t in s.Teams){t.Points=0;t.Wins=0;foreach(var f in t.Facilities.Where(f=>f.Building))f.Due-=365;foreach(var pr in t.Projects){if(pr.TargetYear<s.Year)pr.Gain*=Research.Carryover;pr.TargetYear=s.Year;pr.Start-=365;pr.DesignEnd-=365;pr.Due-=365;}for(int i=0;i<6;i++)t.Base[i]=Clamp(t.Base[i]-1.5-Rand(s)*2.5,55,97);foreach(var part in t.Parts){part.Bonus*=Research.Carryover;if(part.TraitBonus!=null)part.TraitBonus=part.TraitBonus.Select(v=>v*Research.Carryover).ToArray();}Powertrain.Reset(t);Research.Adopt(s,t);t.ResearchSpent=0;t.NextResearchDay=0;if(t.NextEngineYear==s.Year){t.Engine=t.NextEngine;t.EngineUntil=t.NextEngineUntil;t.NextEngine=null;t.NextEngineYear=0;int ei=Array.IndexOf(Data.Engines,t.Engine);t.EngineRating=Data.EnginePower[ei];t.EngineReliability=Data.EngineReliability[ei];}else if(!t.Works){int ei=Array.IndexOf(Data.Engines,t.Engine);t.EngineRating=Data.EnginePower[ei]+Math.Min(4,(s.Year-2026)*.4);t.EngineReliability=Data.EngineReliability[ei];}else {t.EngineRating=Clamp(t.EngineRating-1,65,99);if(t.Id!=s.Player)t.EngineRating=Clamp(t.EngineRating+2,65,99);}if(t.Id!=s.Player&&t.EngineUntil<s.Year)t.EngineUntil=s.Year+2;}
foreach(var p in s.People){p.Points=0;p.Podiums=0;p.Finishes.Clear();if(p.Retired)continue;p.Age++;if(p.Kind==0&&p.RetireYear>0&&p.RetireYear<s.Year){p.Retired=true;p.Deal=null;Note(s,p.Name+" завершил карьеру.");continue;}p.Rating=(int)Clamp(p.Rating+(p.Kind==0?(p.Age<27?(int)(Rand(s)*3):p.Age>35?-(int)(Rand(s)*3):0):Rand(s)<.25?1:0),55,99);if(p.Deal!=null&&p.Deal.Until<s.Year){if(p.Deal.Team==s.Player||s.Bookings.Any(b=>b.Person==p.Id)){if(p.Deal.Team==s.Player)Note(s,"Истёк контракт: "+p.Name+".");p.Deal=null;}else {p.Deal.Salary=Market(p);p.Deal.Start=s.Year;p.Deal.Until=s.Year+1;}}}
foreach(var b in s.Bookings.Where(b=>b.Deal.Start==s.Year).ToList()){var p=Person(s,b.Person);if(p.Retired){s.Bookings.Remove(b);Note(s,p.Name+": будущее соглашение отменено из-за ухода из спорта.");continue;}var old=s.People.FirstOrDefault(x=>x.Id!=p.Id&&x.Kind==p.Kind&&x.Deal!=null&&x.Deal.Team==b.Deal.Team&&x.Deal.Seat==b.Deal.Seat);if(old!=null)old.Deal=null;p.Deal=b.Deal;ResetChemistry(s,p);s.Bookings.Remove(b);Note(s,p.Name+": вступил в силу забронированный контракт.");}
for(int i=0;i<3;i++)Generate(s,0);for(int k=1;k<=5;k++)Generate(s,k);FillAI(s);Advance(s,0);s.LastCarMetrics=CarModel.Values(Team(s,s.Player));Announce(s);Note(s,"Сезон "+s.Year+": межсезонье открыто. Проверьте свободные места и двигатель.");}
public static string Serialize(Career s){var json=new JavaScriptSerializer{MaxJsonLength=int.MaxValue,RecursionLimit=200};return json.Serialize(s);}
public static Career Deserialize(string text){var json=new JavaScriptSerializer{MaxJsonLength=100000000,RecursionLimit=200};var s=json.Deserialize<Career>(text);Validate(s,true);return s;}
public static void Validate(Career s,bool repairWorkforce=false){bool migrate=s!=null&&(s.Version==2||s.Version==3||s.Version==4);if(s!=null&&s.Version==2){if(s.Weekend!=null&&s.Weekend.Live!=null)foreach(var e in s.Weekend.Live.Entries)e.ScheduledStops=e.Stops;s.Version=3;}if(s!=null&&s.Version==3)s.Version=4;if(s!=null&&s.Version==4){foreach(var team in s.Teams??new List<Team>()){if(team.NextParts==null)team.NextParts=new List<Installed>();team.NextResearchDay=s.Day;}s.Version=5;}if(s!=null&&s.Version==5){foreach(var t in s.Teams??new List<Team>())Powertrain.Reset(t);s.Version=6;}if(s==null||s.Version!=6||s.Year<2026||s.Year>2200||s.Round<0||s.Round>Data.Tracks.Length||s.Teams==null||s.People==null||s.Teams.Count<11||s.Teams.Count>12||s.People.Count>10000||s.Teams.All(t=>t.Id!=s.Player)||double.IsNaN(s.Cash)||double.IsInfinity(s.Cash))throw new Exception("Некорректный файл карьеры версии 2/3/4/5/6.");if(s.Bookings==null||s.Archive==null||s.Hall==null||s.News==null||s.Ledger==null||s.Plans==null||s.People.Select(p=>p.Id).Distinct().Count()!=s.People.Count)throw new Exception("Повреждены списки карьеры.");foreach(var t in s.Teams){if(t.Base==null||t.Base.Length!=6||t.Facilities==null||t.Facilities.Length!=6||t.Facilities.Any(f=>f.Level<1||f.Level>5)||!Data.Engines.Contains(t.Engine)||t.Parts==null||t.Projects==null||t.Projects.Any(p=>!Data.Parts.Any(c=>c.Key==p.Key)||p.Engineers<1)||t.Parts.Any(p=>!Data.Parts.Any(c=>c.Key==p.Key)))throw new Exception("Повреждены данные команды.");foreach(int kind in Enumerable.Range(0,6)){int k=kind;if(s.People.Where(p=>p.Kind==k&&p.Deal!=null&&p.Deal.Team==t.Id).GroupBy(p=>p.Deal.Seat).Any(g=>g.Count()>1))throw new Exception("Дублируются контракты.");}}if(s.People.Any(p=>p.Name==null||p.Kind<0||p.Kind>5||p.Rating<0||p.Rating>100||p.Deal!=null&&(!s.Teams.Any(t=>t.Id==p.Deal.Team)||p.Deal.Salary<0||double.IsNaN(p.Deal.Salary))))throw new Exception("Повреждены контракты.");if(!s.SeasonDone&&(s.Round==Data.Tracks.Length||s.Stage<0||s.Stage>=Sessions(s).Length))throw new Exception("Повреждено состояние сезона.");if(s.Weekend!=null&&s.Weekend.Live!=null&&s.Weekend.Live.Entries.Any(e=>!s.People.Any(p=>p.Id==e.Id)))throw new Exception("Повреждена активная сессия.");if(migrate){if(s.EngineeringReports==null)s.EngineeringReports=new List<EngineeringReport>();if(s.UpgradeTrials==null)s.UpgradeTrials=new List<UpgradeReview>();if(s.LastCarMetrics==null)s.LastCarMetrics=CarModel.Values(Team(s,s.Player));}Engineering.Validate(s);Research.Validate(s);Powertrain.Validate(s);RaceDirector.Validate(s);if(repairWorkforce)Research.ReconcileWorkforce(s);Research.ValidateWorkforce(s);}
public static void Save(Career s,string path){Validate(s);string dir=Path.GetDirectoryName(path);Directory.CreateDirectory(dir);string tmp=path+".tmp";File.WriteAllText(tmp,Serialize(s),new UTF8Encoding(false));if(File.Exists(path))File.Replace(tmp,path,path+".bak",true);else File.Move(tmp,path);}
}}
